                anchorMonth.Year, anchorMonth.Month, Math.Min(birth.Day, DateTime.DaysInMonth(anchorMonth.Year, anchorMonth.Month)));
            days = (int)(at.Date - anchor).TotalDays - earlier;
        }
        return (totalMonths / 12, totalMonths % 12, days);
    }
